async function killRat(timeoutMs = 120000) {
  const start = Date.now();
  let attackedIdx = null;
  while (Date.now() - start < timeoutMs) {
    await bot.dismissBlockingUI().catch(()=>{});
    const s = sdk.getState();
    if (s.player.hp <= 7) {
      const food = sdk.findInventoryItem(/bread|shrimp/i);
      if (food) { await bot.eatFood(food); continue; }
    }
    const s2 = sdk.getState();
    const rats = s2.nearbyNpcs.filter(n => /giant rat/i.test(n.name));
    if (!rats.length) return { done: true, reason: 'no_rats' };
    if (attackedIdx !== null && !s2.nearbyNpcs.some(n => n.index === attackedIdx)) return { done: true, reason: 'killed' };
    if (!s2.player.combat.inCombat) {
      const target = rats.sort((a,b) => (b.level||0) - (a.level||0) || a.distance - b.distance)[0];
      const res = await bot.attack(target).catch(e => ({ success: false }));
      if (res.success || res.reason === 'already_in_combat' || res.reason === 'timeout') {
        attackedIdx = target.index;
      }
      continue;
    }
    await new Promise(r => setTimeout(r, 500));
  }
  return { done: false, reason: 'timeout' };
}
