async function killOne(pattern, timeoutMs = 90000) {
  const start = Date.now();
  let attackedIdx = null;
  while (Date.now() - start < timeoutMs) {
    await bot.dismissBlockingUI().catch(()=>{});
    const s = sdk.getState();
    if (s.player.hp <= 6) {
      const food = sdk.findInventoryItem(/bread|shrimp/i);
      if (food) { await bot.eatFood(food); continue; }
      else return { done: false, reason: 'no_food' };
    }
    if (s.player.isDead) return { done: false, reason: 'died' };
    if (s.player.combat.inCombat) {
      await new Promise(r => setTimeout(r, 500));
      continue;
    }
    const target = s.nearbyNpcs.filter(n => pattern.test(n.name)).sort((a,b) => a.distance - b.distance)[0];
    if (!target) return { done: true, reason: 'npc_gone' };
    if (attackedIdx !== null && !s.nearbyNpcs.some(n => n.index === attackedIdx)) return { done: true, reason: 'killed' };
    const res = await bot.attack(target).catch(() => ({ success: false }));
    if (res.success || res.reason === 'already_in_combat' || res.reason === 'timeout') attackedIdx = target.index;
    await new Promise(r => setTimeout(r, 600));
  }
  return { done: false, reason: 'timeout' };
}
